const cfg = $('Set Config Parameters').first().json;
let projects = Array.isArray(cfg.projects) ? cfg.projects : JSON.parse(cfg.projects);

// The restart form only scans the project the person chose (a project can span several clusters)
if (cfg.mode === 'restart' && new Set(projects.map(p => p.project)).size > 1) {
  const chosen = $('Select Project Form').first().json['Project'];
  projects = projects.filter(p => p.project === chosen);
}

return projects.map(p => ({ json: {
  project: p.project,
  account: p.account,
  region: p.region || 'us-east-1',
  cluster: p.cluster,
} }));

// DescribeServices accepts at most 10 services per call
return $input.all().flatMap(item => {
  const { response, ...project } = item.json;
  const arns = response?.serviceArns || [];
  const batches = [];
  for (let i = 0; i < arns.length; i += 10) {
    batches.push({ json: { ...project, services: arns.slice(i, i + 10) } });
  }
  return batches;
});

const cfg = $('Set Config Parameters').first().json;
const mode = cfg.mode;
const now = new Date();

const services = $input.all()
  .flatMap(i => (i.json.response?.services || []).map(s => ({ ctx: i.json, s })))
  .filter(({ s }) => s.status === 'ACTIVE')
  .map(({ ctx, s }) => {
    const tags = Object.fromEntries((s.tags || []).map(t => [t.key, t.value]));
    const saved = tags['saved-desired-count'];
    return {
      project: ctx.project,
      account: ctx.account,
      region: ctx.region,
      cluster: ctx.cluster,
      name: s.serviceName,
      arn: s.serviceArn,
      displayName: tags['display-name'] || s.serviceName,
      desiredCount: s.desiredCount,
      runningCount: s.runningCount,
      scheduled: tags[cfg.scheduleTagKey] === cfg.scheduleTagValue,
      savedCount: saved !== undefined ? Math.max(1, parseInt(saved, 10) || cfg.defaultDesiredCount) : null,
      overrideUntil: tags['override-until'] || null,
    };
  })
  // Only services carrying the schedule tag are ever touched
  .filter(s => s.scheduled);

if (mode === 'stop') {
  // Skip services restarted via the form whose time isn't up yet
  return services
    .filter(s => s.desiredCount > 0)
    .filter(s => !(s.overrideUntil && new Date(s.overrideUntil) > now))
    .map(s => ({ json: { mode, ...s } }));
}

if (mode === 'start') {
  // Only services this workflow stopped (they carry the saved count)
  return services
    .filter(s => s.savedCount !== null)
    .map(s => ({ json: { mode, ...s } }));
}

// restart: one item holding the services that can be
//  - started:  stopped by the schedule, or
//  - extended: running from an earlier form request whose time isn't up yet
const hhmm = iso => DateTime.fromISO(iso).setZone(cfg.timezone).toFormat('HH:mm');
const options = services
  .filter(s => s.savedCount !== null && (s.desiredCount === 0 || (s.overrideUntil && new Date(s.overrideUntil) > now)))
  .map(s => {
    const base = s.displayName === s.name ? s.name : `${s.displayName} (${s.name})`;
    const running = s.desiredCount > 0;
    return { ...s, running, label: running ? `${base} – running until ${hhmm(s.overrideUntil)} (extend)` : base };
  });
return [{ json: { mode, options } }];

const cfg = $('Set Config Parameters').first().json;
const svcs = $input.all().map(i => i.json);
if (!svcs.length) return [];
return [{ json: {
  title: `🌙 Nightly stop: ${svcs.length} service(s) switched off`,
  lines: [
    ...svcs.map(s => `• ${s.project} / ${s.displayName}`),
    `Need one tonight? Use the restart page: ${cfg.restartFormUrl}`,
  ],
} }];

const svcs = $input.all().map(i => i.json);
if (!svcs.length) return [];
return [{ json: {
  title: `☀️ Morning start: ${svcs.length} service(s) switched on`,
  lines: svcs.map(s => `• ${s.project} / ${s.displayName} (${s.savedCount} task${s.savedCount === 1 ? '' : 's'})`),
} }];

const cfg = $('Set Config Parameters').first().json;
const req = $('When Restart Requested').first().json;
const pick = $input.first().json;
const options = $('Check Services to Restart').first().json.options;

// Multi-select may arrive as an array or a JSON string
let chosen = pick['Services'];
if (typeof chosen === 'string') {
  try { chosen = JSON.parse(chosen); } catch (e) { chosen = [chosen]; }
}
chosen = [].concat(chosen);

// Re-check against the tagged list so only eligible services can be started or extended
const picked = chosen.map(label => options.find(o => o.label === label)).filter(Boolean);
if (!picked.length) throw new Error(`None of the selected services can be started or extended: ${chosen.join(', ')}`);
if (picked.length > 10) throw new Error('Please choose 10 services or fewer per request.');

const now = DateTime.now().setZone(cfg.timezone);
const duration = pick['How long do you need them?'];
const fmt = d => d.setZone(cfg.timezone).toFormat('ccc d LLL, HH:mm');

function nextOfficeStart(from) {
  let d = from.set({ hour: cfg.officeStartHour, minute: 0, second: 0, millisecond: 0 });
  if (d <= from) d = d.plus({ days: 1 });
  while (d.weekday > 5) d = d.plus({ days: 1 });
  return d;
}

// Same labels as the Select ECS Services dropdown (built from durationHours)
const label = h => h < 1 ? Math.round(h * 60) + ' minutes' : (h === 1 ? '1 hour' : h + ' hours');
const hours = (cfg.durationHours || []).find(h => label(h) === duration);

// The time counts from now, for both new starts and extensions
let until;
if (hours !== undefined) until = now.plus({ minutes: Math.round(hours * 60) });
else until = nextOfficeStart(now); // 'Until the next working-day morning'

// An extension never shortens: skip running services already booked past the new end time
const svcs = picked.filter(s => !(s.running && DateTime.fromISO(s.overrideUntil) >= until));
if (!svcs.length) {
  throw new Error(`The selected services are already running until after ${fmt(until)}, so there is nothing to extend.`);
}

return svcs.map(svc => ({ json: {
  action: svc.running ? 'extend' : 'start',
  project: svc.project,
  account: svc.account,
  region: svc.region,
  cluster: svc.cluster,
  service: svc.name,
  arn: svc.arn,
  displayName: svc.displayName,
  desiredCount: svc.savedCount,
  previousUntilLocal: svc.running ? fmt(DateTime.fromISO(svc.overrideUntil)) : null,
  duration,
  overrideUntil: until.toUTC().toISO({ suppressMilliseconds: true }),
  overrideUntilLocal: fmt(until),
  requestedBy: req['Your name'],
  reason: req['Reason'],
} }));

const reqs = $('Prepare ECS Restart').all().map(i => i.json);
const r = reqs[0];
const started = reqs.filter(x => x.action === 'start');
const extended = reqs.filter(x => x.action === 'extend');

const title = started.length
  ? `🚀 Starting ${started.length} service(s) in ${r.project}` + (extended.length ? `, extending ${extended.length}` : '')
  : `⏩ Extended ${extended.length} service(s) in ${r.project}`;

return [{ json: {
  title,
  lines: [
    ...started.map(x => `• ${x.displayName}`),
    ...extended.map(x => `• ${x.displayName} (extended – was until ${x.previousUntilLocal})`),
    `Requested by ${r.requestedBy}: ${r.reason}`,
    `Duration: ${r.duration} (until ${r.overrideUntilLocal})`,
  ],
} }];

// One DescribeServices call per account/region/cluster in this request
const groups = {};
for (const r of $('Prepare ECS Restart').all().map(i => i.json)) {
  const key = [r.account, r.region, r.cluster].join('|');
  (groups[key] ??= { account: r.account, region: r.region, cluster: r.cluster, services: [] }).services.push(r.service);
}
return Object.values(groups).map(g => ({ json: g }));

const cfg = $('Set Config Parameters').first().json;
const names = Object.fromEntries($('Prepare ECS Restart').all().map(i => [i.json.service, i.json.displayName]));
const attempt = $runIndex + 1;

const details = $input.all().flatMap(i => i.json.response?.services || []).map(s => ({
  name: names[s.serviceName] || s.serviceName,
  running: s.runningCount ?? 0,
  desired: s.desiredCount ?? 0,
  ready: s.desiredCount > 0 && s.runningCount >= s.desiredCount && (s.pendingCount || 0) === 0,
  lastEvent: (s.events || [])[0]?.message || 'none',
}));

const allReady = details.length > 0 && details.every(d => d.ready);
const status = allReady ? 'ready' : (attempt >= cfg.maxHealthChecks ? 'failed' : 'waiting');
return [{ json: { status, attempt, details } }];

const r = $('Prepare ECS Restart').first().json;
const h = $input.first().json;
return [{ json: {
  title: `✅ Ready in ${r.project}`,
  lines: [
    ...h.details.map(d => `• ${d.name}: ${d.running}/${d.desired} task(s) running`),
    `Requested by ${r.requestedBy}. Switches off again at ${r.overrideUntilLocal}.`,
  ],
} }];

const r = $('Prepare ECS Restart').first().json;
const h = $input.first().json;
const minutes = Math.round(h.attempt * 30 / 60);
return [{ json: {
  title: `⚠️ Not all services became healthy in ${r.project}`,
  lines: [
    ...h.details.map(d => `• ${d.name}: ${d.running}/${d.desired} running${d.ready ? '' : ` – latest event: ${d.lastEvent}`}`),
    `Checked for ${minutes} minutes. Engineering: please take a look. Requested by ${r.requestedBy}.`,
  ],
} }];

// One DescribeServices call per account/region/cluster in this request
const groups = {};
for (const r of $('Prepare ECS Restart').all().map(i => i.json)) {
  const key = [r.account, r.region, r.cluster].join('|');
  (groups[key] ??= { account: r.account, region: r.region, cluster: r.cluster, services: [] }).services.push(r.service);
}
return Object.values(groups).map(g => ({ json: g }));

// Stop again only outside office hours, and only services whose override wasn't changed by someone else
const cfg = $('Set Config Parameters').first().json;
const reqs = $('Prepare ECS Restart').all().map(i => i.json);
const now = DateTime.now().setZone(cfg.timezone);
const inOfficeHours = now.weekday <= 5 && now.hour >= cfg.officeStartHour && now.hour < cfg.officeEndHour;
if (inOfficeHours) return [];

return $input.all().flatMap(i => i.json.response?.services || [])
  .filter(s => {
    const tags = Object.fromEntries((s.tags || []).map(t => [t.key, t.value]));
    return tags['override-until'] === reqs[0].overrideUntil && (s.desiredCount || 0) > 0;
  })
  .map(s => ({ json: reqs.find(r => r.service === s.serviceName && r.cluster === s.clusterArn.split('/').pop()) }))
  .filter(i => i.json);

const stopped = $input.all().map(i => i.json);
const r = stopped[0];
return [{ json: {
  title: `⏹ Switched off again in ${r.project}`,
  lines: [
    ...stopped.map(s => `• ${s.displayName}`),
    `The requested time (${r.duration}) for ${r.requestedBy} has ended.`,
  ],
} }];

// Hand the caller back its context plus the ECS response
const req = $('On ECS API Call').first().json;
// ECS replies with content-type application/x-amz-json-1.1, which n8n returns as text in `data`, so parse it
const raw = $input.first().json;
let response = raw;
if (typeof raw.data === 'string') {
  try { response = raw.data ? JSON.parse(raw.data) : {}; }
  catch (e) { throw new Error(`Could not parse ECS ${req.action} response: ${raw.data.slice(0, 300)}`); }
}
return [{ json: { ...(req.context || {}), response } }];
